import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/c_analisi/cd/cdd1.md","filePath":"lezioni/c_analisi/cd/cdd1.md"}`),a={name:`lezioni/c_analisi/cd/cdd1.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<blockquote><p class="text-red">[<strong>Nota con un po&#39; di filosofia</strong>]</p><p>Veramente il fatto di avere un intorno di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi mathvariant="normal">∞</mi></mrow><annotation encoding="application/x-tex">\\infty</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord">∞</span></span></span></span> che si stringe è una cosa che rende piuttosto perplessi: infatti se considero il <a href="./../../a/ad/pvista.html">punto di vista</a> del punto <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi mathvariant="normal">∞</mi></mrow><annotation encoding="application/x-tex">\\infty</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord">∞</span></span></span></span> cosa significa che il suo intorno si stringe? In effetti non significa nulla: un intorno infinito resta sempre un intorno infinito per quanto io cerchi di stringerlo. Anche dal punto di vista dell&#39;intervallo abbiamo dei problemi: come può stringersi un intervallo che contenga l&#39;infinito? L&#39;unica cosa che possiamo vedere è che il bordo dell&#39;intorno o il bordo dell&#39;intervallo si allontana da un qualunque punto prefissato di quantità sempre maggiori; cioè il concetto di limite infinito non è una cosa oggettiva ma una cosa dipendente dall&#39;osservatore.</p><p>Le scuole matematiche sono sempre state due, quelle che io chiamo i pitagorici e gli aristotelici: i pitagorici pensano che la matematica sia la realtà, gli aristotelici invece pensano che la matematica sia una costruzione umana e che abbia riscontro nella realtà in quanto la realtà stessa viene filtrata attraverso il nostro cervello: il concetto di limite infinito è una concezione non accettabile per i pitagorici ma in linea con il pensiero matematico aristotelico.</p><p>In pratica, siccome la matematica ci serve, la costruiamo sulla nostra misura, quindi anche il concetto di infinito, anche se non è il concetto oggettivo di infinito, è un concetto che per noi e per i nostri bisogni è più che sufficiente, anche se, secondo me, è piuttosto riduttivo.</p><p>Per vederne l&#39;equivalente geometrico pensate una retta ed un punto fuori di essa, se dal punto traccio una retta obliqua questa incontrerà la prima retta in un punto <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>A</mi></mrow><annotation encoding="application/x-tex">A</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span></span></span></span>, se ora ruoto la retta, fino a farla diventare parallela, il punto si sposterà fino all&#39;infinito e quando la retta sarà parallela il punto sparirà, ma non appena ruoterò la retta anche di un millesimo di grado il punto ricomparirà dall&#39;altra parte.</p><p>Questo ragionamento è valido finché io sto al finito a guardare cosa succede.</p><p>Quindi mettendoci sul punto di vista del finito considereremo ad esempio una retta come una circonferenza di raggio <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi mathvariant="normal">∞</mi></mrow><annotation encoding="application/x-tex">\\infty</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord">∞</span></span></span></span> in cui l&#39;infinito (senza segno) è un punto, ed invece in analisi considereremo l&#39;infinito talvolta un punto solo e quindi senza segno (oppure con <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>±</mo><mi mathvariant="normal">∞</mi></mrow><annotation encoding="application/x-tex">\\pm\\infty</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord">±</span><span class="mord">∞</span></span></span></span>) e talvolta come due punti: uno col segno positivo ed uno col segno negativo.</p></blockquote>`,1)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};